const LANGUAGE_STORAGE_KEY = 'guesthouse-platform-language';
const LanguageContext = createContext({
  language: 'en',
  languages: LANGUAGES,
  setLanguage: () => {},
  t: (text) => text,
});

function getInitialLanguage() {
  try {
    const savedLanguage = localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return LANGUAGES.some(({ code }) => code === savedLanguage) ? savedLanguage : 'en';
  } catch {
    return 'en';
  }
}

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(getInitialLanguage);

  useEffect(() => {
    const selectedLanguage = LANGUAGES.find(({ code }) => code === language);
    document.documentElement.lang = selectedLanguage?.locale || 'en-US';
    document.title = translations[language]?.['Guesthouse Reservation Platform'] || 'Guesthouse Reservation Platform';
    try {
      localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
    } catch {
      // Keep the selected language for this session if storage is unavailable.
    }
  }, [language]);

  const t = (text, values = {}) => {
    const translated = translations[language]?.[text] || text;
    return translated.replace(/\{\{(\w+)\}\}/g, (placeholder, key) =>
      values[key] === undefined ? placeholder : String(values[key])
    );
  };

  return (
    <LanguageContext.Provider value={{ language, languages: LANGUAGES, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  return useContext(LanguageContext);
}